library(readr)
library(dplyr)
library(labelled)

# Helper to read a file if exists
read_if_exists <- function(path){
  if(file.exists(path) && file.info(path)$size>0){
    read_delim(path, delim='\t', col_types = cols(.default = col_guess()), show_col_types=FALSE)
  } else {
    NULL
  }
}

# Define file list and required columns
files <- list(
  'wave_one_lsype_young_person_2020.tab' = c('NSID'),
  'wave_four_lsype_young_person_2020.tab' = c('NSID','W4nsseccatYP'),
  'wave_five_lsype_young_person_2020.tab' = c('NSID','W5nsseccatYP'),
  'wave_six_lsype_young_person_2020.tab' = c('NSID','w6nsseccatYP'),
  'wave_seven_lsype_young_person_2020.tab' = c('NSID','W7NSSECCat'),
  'ns8_2015_derived.tab' = c('NSID','W8DACTIVITYC','W8DNSSEC17'),
  'ns9_2022_main_interview.tab' = c('NSID','W9NSSEC')
)

# Load all files
dfs <- lapply(names(files), function(f){
  path <- file.path('data','input',f)
  df <- read_if_exists(path)
  if(!is.null(df)){
    # Ensure required columns present
    missing <- setdiff(files[[f]], names(df))
    if(length(missing)>0){
      df[missing] <- NA
    }
  }
  df
})

dfs <- dfs[!sapply(dfs, is.null)]

# Merge by NSID
merged <- dfs[[1]]
if(length(dfs)>1){
  for(i in 2:length(dfs)){
    merged <- full_join(merged, dfs[[i]], by='NSID')
  }
}

# Standardise missing values
std_missing <- function(x){
  case_when(
    is.na(x) ~ NA_real_,
    x %in% c(-999,-998,-997,-995) ~ -9,
    x %in% c(-99) ~ -3,
    x %in% c(-91) ~ -1,
    x %in% c(-9) ~ -9,
    x %in% c(-8) ~ -8,
    x %in% c(-7) ~ -7,
    x %in% c(-3) ~ -3,
    x %in% c(-2) ~ -2,
    x %in% c(-1) ~ -1,
    TRUE ~ x
  )
}

# NS-SEC labels for major categories
nssec_labels <- c(
  '1'='Employers in large organisations',
  '2'='Higher managerial and administrative occupations',
  '3'='Higher professional occupations',
  '4'='Lower professional and higher technical occupations',
  '5'='Lower managerial and administrative occupations',
  '6'='Higher supervisory occupations',
  '7'='Intermediate occupations',
  '8'='Employers in small establishments',
  '9'='Own account workers',
  '10'='Lower supervisory occupations',
  '11'='Lower technical occupations',
  '12'='Semi-routine occupations',
  '13'='Routine occupations',
  '14'='Never worked and Long-term unemployed',
  '15'='Full-time students',
  '16'='Occupations not stated or inadequately described',
  '17'='Not classifiable for other reasons',
  '-9'='Refusal',
  '-8'='Insufficient information',
  '-7'='Prefer not to say',
  '-3'='Not asked at the fieldwork stage / not interviewed',
  '-2'='Schedule not applicable / script error / information lost',
  '-1'='Item not applicable'
)

# Function to create labelled numeric vector (using labelled::labelled)
labelled_vec <- function(x){
  labelled::labelled(x, nssec_labels)
}

# Derive NS-SEC variables
merged <- merged %>%
  mutate(
    nssec17 = labelled_vec(ifelse(is.na(std_missing(W4nsseccatYP), -3, floor(std_missing(W4nsseccatYP))), ),
    nssec18 = labelled_vec(ifelse(is.na(std_missing(W5nsseccatYP), -3, floor(std_missing(W5nsseccatYP))), ),
    nssec19 = labelled_vec(ifelse(is.na(std_missing(w6nsseccatYP), -3, floor(std_missing(w6nsseccatYP))), ),
    nssec20 = labelled_vec(ifelse(is.na(std_missing(W7NSSECCat), -3, floor(std_missing(W7NSSECCat))), ),
    nssec25_raw = {
      if(!is.na(W8DACTIVITYC) && W8DACTIVITYC == 5){
        15
      } else {
        val <- std_missing(W8DNSSEC17)
        if(is.na(val)) -3 else floor(val)
      }
    },
    nssec25 = labelled_vec(nssec25_raw),
    nssec32 = {
      if('W9NSSEC' %in% names(.)){
        labelled_vec(ifelse(is.na(std_missing(W9NSSEC)), -3, floor(std_missing(W9NSSEC))))
      } else {
        NA_real_
      }
    }
  )

# Select final variables
