library(dplyr)
library(labelled)
library(tidyr)
library(purrr)

# Map of file names to expected variables
file_vars <- list(
  'wave_one_lsype_young_person_2020.tab' = c('NSID'),
  'wave_four_lsype_young_person_2020.tab' = c('NSID','W4nsseccatYP'),
  'wave_five_lsype_young_person_2020.tab' = c('NSID','W5nsseccatYP'),
  'wave_six_lsype_young_person_2020.tab' = c('NSID','w6nsseccatYP'),
  'wave_seven_lsype_young_person_2020.tab' = c('NSID','W7NSSECCat'),
  'ns8_2015_derived.tab' = c('NSID','W8DACTIVITYC','W8DNSSEC17'),
  'ns9_2022_main_interview.tab' = c('NSID','W9NSSEC')
)

# Function to load a file if it exists and not empty
load_file <- function(fname, vars){
  path <- file.path('data','input',fname)
  if(!file.exists(path) || file.info(path)$size==0){
    warning(paste('Skipping file',fname,'(missing or empty)'))
    return(NULL)
  }
  df <- read_delim(path, delim='\t', col_types = cols(.default = col_guess()), show_col_types=FALSE)
  # Ensure required columns exist
  missing_vars <- setdiff(vars, names(df))
  if(length(missing_vars)>0){
    warning(paste('File',fname,'missing columns',paste(missing_vars, collapse=',')))
    df[missing_vars] <- NA
  }
  return(df)
}

# Load all files
all_dfs <- map(file_vars, load_file)
# Remove NULLs
all_dfs <- all_dfs[!sapply(all_dfs,is.null)]

# Merge sequentially by NSID
merged_all <- all_dfs[[1]]
if(length(all_dfs)>1){
  for(i in 2:length(all_dfs)){
    merged_all <- full_join(merged_all, all_dfs[[i]], by='NSID')
  }
}

# Helper: standardise missing codes
standardize_missing <- function(x){
  x_clean <- case_when(
    is.na(x) ~ NA_real_,
    x %in% c(-999,-998,-997,-995) ~ -9,
    x %in% c(-99) ~ -3,
    x %in% c(-91) ~ -1,
    x %in% c(-9) ~ -9,
    x %in% c(-8) ~ -8,
    x %in% c(-7) ~ -7,
    x %in% c(-3) ~ -3,
    x %in% c(-2) ~ -2,
    x %in% c(-1) ~ -1,
    TRUE ~ x
  )
  return(x_clean)
}

# Value labels for NS-SEC major categories
nssec_labels <- c(
  '-9'='Refusal',
  '-8'='Insufficient information',
  '-7'='Prefer not to say',
  '-3'='Not asked at the fieldwork stage / not interviewed',
  '-2'='Schedule not applicable / script error / information lost',
  '-1'='Item not applicable',
  '1'='Employers in large organisations',
  '2'='Higher managerial and administrative occupations',
  '3'='Higher professional occupations',
  '4'='Lower professional and higher technical occupations',
  '5'='Lower managerial and administrative occupations',
  '6'='Higher supervisory occupations',
  '7'='Intermediate occupations',
  '8'='Employers in small establishments',
  '9'='Own account workers',
  '10'='Lower supervisory occupations',
  '11'='Lower technical occupations',
  '12'='Semi-routine occupations',
  '13'='Routine occupations',
  '14'='Never worked and Long-term unemployed',
  '15'='Full-time students',
  '16'='Occupations not stated or inadequately described',
  '17'='Not classifiable for other reasons'
)

# Derive NS-SEC variables for each wave
merged_all <- merged_all %>%
  mutate(
    nssec17 = {
      v <- standardize_missing(W4nsseccatYP)
      if(is.na(v)) -3 else floor(v)
    },
    nssec18 = {
      v <- standardize_missing(W5nsseccatYP)
      if(is.na(v)) -3 else floor(v)
    },
    nssec19 = {
      v <- standardize_missing(w6nsseccatYP)
      if(is.na(v)) -3 else floor(v)
    },
    nssec20 = {
      v <- standardize_missing(W7NSSECCat)
      if(is.na(v)) -3 else floor(v)
    },
    nssec25_raw = {
      if(!is.na(W8DACTIVITYC) && W8DACTIVITYC == 5){
        15
      } else {
        v <- standardize_missing(W8DNSSEC17)
        if(is.na(v)) -3 else floor(v)
      }
    },
    nssec25 = as_factor(labelled(nssec25_raw, nssec_labels)),
    nssec32 = {
      if('W9NSSEC' %in% names(.)){ 
        v <- standardize_missing(W9NSSEC)
        if(is.na(v)) -3 else floor(v)
      } else {
        NA_real_
      }
    }
  )

# Convert to labelled factors
merged_all <- merged_all %>%
  mutate(
    nssec17 = as_factor(labelled(nssec17, nssec_labels)),
    nssec18 = as_factor(labelled(nssec18, nssec_labels)),
    nssec19 = as_factor(labelled(nssec19, nssec_labels)),
    nssec20 = as_factor(labelled(nssec20, nssec_labels)),
    nssec32 = as_factor(labelled(nssec32, nssec_labels))
  )

# Final selection
final_df <- merged_all %>% select(NSID, nssec17, nssec18, nssec19, nssec20, nssec25, nssec32)

# Write CSV
write_csv(final_df, 'data/output/cleaned_data.csv')

print('Script completed successfully.')
"}}}]

