  if (file.exists(path) && file.info(path)$size > 0) {
    read_delim(path,
               delim = "\t",
               col_types = cols(.default = col_guess()),
               show_col_types = FALSE)
  } else {
    NULL
  }
}

# standardise_missing ---------------------------------------------
