  act_val <- get_col("W8DACTIVITYC")
  if (!is.na(act_val) && act_val == 5) {
    15
  } else {
    val <- standardise_missing(get_col("W8DNSSEC17"))
    if (is.na(val)) -3 else floor(val)
  }
}

# nssec32 (Wave 9, age 32)
nssec32_val <- {
  if ("W9NSSEC" %in% names(merged)) {
    val <- standardise_missing(get_col("W9NSSEC"))
    if (is.na(val)) -3 else floor(val)
  } else {
    NA_real_
  }
}

# ------------------------------------------------------------------
# Build final dataframe ---------------------------------------------
