library(readr)
library(dplyr)

# ------------------------------------------------------------------
# Utility functions ------------------------------------------------
# read_if_exists ---------------------------------------------------
read_if_exists <- function(path) {
  if (file.exists(path) && file.info(path)$size > 0) {
    read_delim(path,
               delim = "\t",
               col_types = cols(.default = col_guess()),
               show_col_types = FALSE)
  } else {
    NULL
  }
}

# standardise_missing ---------------------------------------------
standardise_missing <- function(x) {
  case_when(
    is.na(x)                                  ~ NA_real_,
    x %in% c(-999, -998, -997, -995)            ~ -9,
    x %in% c(-99)                              ~ -3,
    x %in% c(-91)                              ~ -1,
    x %in% c(-9)                               ~ -9,
    x %in% c(-8)                               ~ -8,
    x %in% c(-7)                               ~ -7,
    x %in% c(-3)                               ~ -3,
    x %in% c(-2)                               ~ -2,
    x %in% c(-1)                               ~ -1,
    TRUE                                       ~ x
  )
}

# ------------------------------------------------------------------
# Load data --------------------------------------------------------
file_list <- list(
  "wave_one_lsype_young_person_2020.tab"      = c("NSID"),
  "wave_four_lsype_young_person_2020.tab"      = c("NSID", "W4nsseccatYP"),
  "wave_five_lsype_young_person_2020.tab"      = c("NSID", "W5nsseccatYP"),
  "wave_six_lsype_young_person_2020.tab"       = c("NSID", "w6nsseccatYP"),
  "wave_seven_lsype_young_person_2020.tab"     = c("NSID", "W7NSSECCat"),
  "ns8_2015_derived.tab"                      = c("NSID", "W8DACTIVITYC", "W8DNSSEC17"),
  "ns9_2022_main_interview.tab"                = c("NSID", "W9NSSEC")
)

# Load each file (if it exists and is not empty)
dfs <- lapply(names(file_list), function(f) {
  path <- file.path("data", "input", f)
  df <- read_if_exists(path)
  if (!is.null(df)) {
    # Ensure all required columns present
    missing_cols <- setdiff(file_list[[f]], names(df))
    if (length(missing_cols) > 0) {
      df[missing_cols] <- NA_real_
    }
  }
  df
})
dfs <- dfs[!sapply(dfs, is.null)]

# Merge by NSID (full join)
merged <- dfs[[1]]
if (length(dfs) > 1) {
  for (i in 2:length(dfs)) {
    merged <- full_join(merged, dfs[[i]], by = "NSID")
  }
}

# ------------------------------------------------------------------
# Derive NS‑SEC variables ------------------------------------------
# Helper to get a value or default if column missing
get_col <- function(col_name, default = NA_real_) {
  if (col_name %in% names(merged)) merged[[col_name]] else default
}

# nssec17 (Wave 4, age 17)
nssec17_val <- {
  val <- standardise_missing(get_col("W4nsseccatYP"))
  if (is.na(val)) -3 else floor(val)
}

# nssec18 (Wave 5, age 18)
nssec18_val <- {
  val <- standardise_missing(get_col("W5nsseccatYP"))
  if (is.na(val)) -3 else floor(val)
}

# nssec19 (Wave 6, age 19)
nssec19_val <- {
  val <- standardise_missing(get_col("w6nsseccatYP"))
  if (is.na(val)) -3 else floor(val)
}

# nssec20 (Wave 7, age 20)
nssec20_val <- {
  val <- standardise_missing(get_col("W7NSSECCat"))
  if (is.na(val)) -3 else floor(val)
}

# nssec25 (Wave 8, age 25) – special rule for full‑time education
nssec25_val <- {
  act_val <- get_col("W8DACTIVITYC")
  if (!is.na(act_val) && act_val == 5) {
    15
  } else {
    val <- standardise_missing(get_col("W8DNSSEC17"))
    if (is.na(val)) -3 else floor(val)
  }
}

# nssec32 (Wave 9, age 32)
nssec32_val <- {
  if ("W9NSSEC" %in% names(merged)) {
    val <- standardise_missing(get_col("W9NSSEC"))
    if (is.na(val)) -3 else floor(val)
  } else {
    NA_real_
  }
}

# ------------------------------------------------------------------
# Build final dataframe ---------------------------------------------
final_df <- data.frame(
  NSID    = merged$NSID,
  nssec17  = nssec17_val,
  nssec18  = nssec18_val,
  nssec19  = nssec19_val,
  nssec20  = nssec20_val,
  nssec25  = nssec25_val,
  nssec32  = nssec32_val,
  stringsAsFactors = FALSE
)

# ------------------------------------------------------------------
# Write output -----------------------------------------------------
write_csv(final_df, "data/output/cleaned_data.csv")

